window.GPME_KNOWLEDGE_LIST_V41=[{"slug":"acceptation-sous-conditions","title":"Acceptation sous conditions","definition":"Décision de conserver un risque connu avec un niveau de surveillance, des limites ou des conditions validées.","kind":"notion"},{"slug":"acteur-du-processus","title":"Acteur du processus","definition":"Personne, service ou outil qui intervient dans une étape ou reçoit une information du processus.","kind":"notion"},{"slug":"actif-immateriel","title":"Actif immatériel","definition":"Ressource non physique pouvant avoir une valeur pour la PME, par exemple une marque, un logiciel, une création ou un savoir-faire.","kind":"notion"},{"slug":"action-corrective","title":"Action corrective","definition":"Action visant la cause d’un dysfonctionnement afin d’éviter ou de réduire sa répétition.","kind":"methode"},{"slug":"action-de-reduction","title":"Action de réduction","definition":"Mesure visant à éviter, réduire, réutiliser, optimiser ou mieux gérer un flux ou un impact, selon le cas.","kind":"methode"},{"slug":"action-de-suivi","title":"Action de suivi","definition":"Action décidée à l’issue d’un échange, avec un responsable, une échéance et un résultat attendu.","kind":"methode"},{"slug":"aipd","title":"AIPD","definition":"Analyse d’impact relative à la protection des données : démarche utilisée lorsqu’un traitement est susceptible d’engendrer un risque élevé pour les droits et libertés des personnes.","kind":"regle"},{"slug":"alerte-argumentee","title":"Alerte argumentée","definition":"Message qui distingue fait, écart, risque/interprétation, cause à vérifier et action ou décision attendue.","kind":"document"},{"slug":"appel-d-offres","title":"Appel d’offres","definition":"Demande formalisée par laquelle un acheteur invite des entreprises à proposer une offre.","kind":"notion"},{"slug":"archivage","title":"Archivage","definition":"Organisation de la conservation des documents selon leur utilité, durée, valeur et règles applicables.","kind":"methode"},{"slug":"aspect-environnemental","title":"Aspect environnemental","definition":"Élément de l’activité qui interagit avec l’environnement : énergie, matières, déchets, déplacements, rejets, etc.","kind":"notion"},{"slug":"avoir","title":"Avoir","definition":"Document qui diminue ou annule tout ou partie d’une facture antérieure ; il modifie donc le solde réellement dû.","kind":"document"},{"slug":"balance-agee","title":"Balance âgée","definition":"État qui classe les créances ou dettes selon leur ancienneté ou leur retard pour faciliter le suivi.","kind":"document"},{"slug":"base-juridique","title":"Base juridique","definition":"Fondement prévu par le RGPD qui permet un traitement de données ; son choix dépend de la finalité et du contexte.","kind":"regle"},{"slug":"besoin","title":"Besoin","definition":"Résultat que l’achat doit permettre d’obtenir ; il doit être formulé avant de choisir une solution ou une marque.","kind":"notion"},{"slug":"besoin-position","title":"Besoin / position","definition":"La position est ce qu’une personne demande ; le besoin est la raison ou l’intérêt sous-jacent qui peut permettre de chercher une solution.","kind":"notion"},{"slug":"besoin-de-competence","title":"Besoin de compétence","definition":"Écart entre les compétences nécessaires à l’activité et celles actuellement disponibles.","kind":"notion"},{"slug":"besoin-de-financement","title":"Besoin de financement","definition":"Montant et calendrier des ressources financières nécessaires pour réaliser l’investissement sans déséquilibrer la PME.","kind":"notion"},{"slug":"besoin-de-recrutement","title":"Besoin de recrutement","definition":"Raison opérationnelle qui justifie un recrutement : remplacement, croissance, nouvelle compétence, charge, etc.","kind":"notion"},{"slug":"besoin-de-veille","title":"Besoin de veille","definition":"Question ou évolution que la PME décide de surveiller dans le temps parce qu’elle peut influencer une décision ou une pratique.","kind":"notion"},{"slug":"besoin-d-information","title":"Besoin d’information","definition":"Information nécessaire pour répondre à une question, réaliser une activité, contrôler une situation ou prendre une décision.","kind":"notion"},{"slug":"besoin-projet","title":"Besoin projet","definition":"Problème à résoudre ou résultat attendu qui justifie le projet.","kind":"notion"},{"slug":"bfr","title":"BFR","definition":"Besoin de financement généré par le décalage entre cycles d’exploitation, notamment stocks, créances et dettes d’exploitation.","kind":"indicateur"},{"slug":"biais-d-enquete","title":"Biais d’enquête","definition":"Effet lié à la formulation, à l’échantillon, au canal ou au contexte qui peut déformer les résultats observés.","kind":"notion"},{"slug":"bon-de-commande","title":"Bon de commande","definition":"Document qui formalise une commande et permet de contrôler ce qui a été demandé.","kind":"document"},{"slug":"bon-de-livraison","title":"Bon de livraison","definition":"Document qui permet de vérifier ce qui a été livré, quand et en quelle quantité.","kind":"document"},{"slug":"budget-d-evenement","title":"Budget d’événement","definition":"Prévision des coûts et, le cas échéant, des recettes ou financements nécessaires à l’organisation d’un événement.","kind":"document"},{"slug":"budget-previsionnel","title":"Budget prévisionnel","definition":"Traduction chiffrée d’hypothèses et d’objectifs pour une période future.","kind":"document"},{"slug":"cahier-des-charges","title":"Cahier des charges","definition":"Document qui décrit un besoin, des contraintes et les résultats attendus avant de choisir une solution.","kind":"document"},{"slug":"calendrier-electoral","title":"Calendrier électoral","definition":"Enchaînement des étapes, délais, informations et dates à respecter pour sécuriser l’organisation.","kind":"document"},{"slug":"canal-de-communication","title":"Canal de communication","definition":"Moyen utilisé pour communiquer, choisi selon l’urgence, la traçabilité, la confidentialité et le besoin d’échange.","kind":"notion"},{"slug":"canal-de-diffusion","title":"Canal de diffusion","definition":"Moyen utilisé pour diffuser un message auprès d’une cible : réseau social, courriel, site, support imprimé, événement, etc.","kind":"notion"},{"slug":"canal","title":"Canal — préciser le sens","definition":"Le mot canal désigne un moyen de communication ou de diffusion. Le choix dépend du contexte et de l’objectif.","kind":"notion"},{"slug":"capacite","title":"Capacité","definition":"Quantité de travail qu’une ressource peut réellement absorber sur la période compte tenu de ses disponibilités et contraintes.","kind":"notion"},{"slug":"capitalisation","title":"Capitalisation","definition":"Démarche qui transforme une expérience ou un savoir détenu par une personne en connaissance conservée et réutilisable par l’organisation.","kind":"methode"},{"slug":"cause-de-lecart","title":"Cause de l’écart","definition":"Élément documenté qui explique tout ou partie d’un écart observé entre une référence et le réalisé.","kind":"notion"},{"slug":"cause-du-dysfonctionnement","title":"Cause du dysfonctionnement","definition":"Élément qui explique l’apparition d’un problème ; il ne doit pas être confondu avec le symptôme visible.","kind":"notion"},{"slug":"cause-du-risque","title":"Cause du risque","definition":"Élément susceptible de provoquer l’événement de risque.","kind":"notion"},{"slug":"cause-racine","title":"Cause racine","definition":"Cause suffisamment profonde pour expliquer pourquoi le problème apparaît ou se répète.","kind":"notion"},{"slug":"cause","title":"Cause — préciser le sens","definition":"Une cause explique un événement ou un écart. Sa formulation doit préciser ce qu’elle explique : risque, dysfonctionnement ou écart chiffré.","kind":"notion"},{"slug":"certification","title":"Certification","definition":"Reconnaissance formelle délivrée selon un référentiel et une procédure déterminés ; son périmètre et ses conditions doivent être identifiés.","kind":"regle"},{"slug":"champ","title":"Champ","definition":"Rubrique destinée à recevoir une information de même nature dans une base, un tableau ou un formulaire.","kind":"notion"},{"slug":"champ-de-formulaire","title":"Champ de formulaire","definition":"Zone d’un formulaire destinée à recueillir une donnée définie, avec un format et une utilité identifiés.","kind":"notion"},{"slug":"champ-d-application","title":"Champ d’application","definition":"Entreprises, opérations, personnes ou situations réellement concernées par une règle.","kind":"regle"},{"slug":"charge-comptable","title":"Charge comptable","definition":"Consommation de ressources comptabilisée pour l’activité ; elle peut être classée selon la méthode d’analyse retenue.","kind":"notion"},{"slug":"charge-de-travail","title":"Charge de travail","definition":"Quantité de travail à réaliser sur une période ou par une ressource.","kind":"notion"},{"slug":"charge-directe-indirecte","title":"Charge directe / indirecte","definition":"Une charge directe peut être affectée sans calcul intermédiaire à un objet de coût ; une charge indirecte nécessite une règle de répartition.","kind":"notion"},{"slug":"charge-variable-fixe","title":"Charge variable / fixe","definition":"Une charge variable évolue avec le niveau d’activité selon le modèle retenu ; une charge fixe reste relativement stable dans la plage étudiée.","kind":"notion"},{"slug":"charge","title":"Charge — préciser le sens","definition":"Le mot « charge » a plusieurs sens en BTS GPME. Distinguez la charge de travail (organisation) de la charge comptable (calcul des coûts).","kind":"notion"},{"slug":"cible-de-communication","title":"Cible de communication","definition":"Public précis auquel le message est destiné.","kind":"notion"},{"slug":"cible-de-prospection","title":"Cible de prospection","definition":"Ensemble de prospects retenus parce qu’ils correspondent à des critères liés à l’objectif commercial.","kind":"notion"},{"slug":"college-electoral","title":"Collège électoral","definition":"Regroupement de salariés utilisé pour organiser la représentation selon les règles applicables.","kind":"regle"},{"slug":"commande","title":"Commande","definition":"Demande ferme du client à rapprocher de l’offre ou du contrat de référence.","kind":"document"},{"slug":"communication-institutionnelle","title":"Communication institutionnelle","definition":"Communication qui présente et valorise l’organisation elle-même, son identité, ses engagements ou son rôle, plutôt qu’une offre commerciale précise.","kind":"notion"},{"slug":"compte-banque-en-comptabilite","title":"Compte banque en comptabilité","definition":"Compte tenu par l’entreprise ; son solde peut différer temporairement du relevé à cause d’opérations non encore rapprochées.","kind":"notion"},{"slug":"compte-de-tiers","title":"Compte de tiers","definition":"Compte comptable individuel ou auxiliaire permettant de suivre les sommes dues par ou à un client/fournisseur.","kind":"notion"},{"slug":"compte-rendu-actionnable","title":"Compte rendu actionnable","definition":"Trace des décisions et actions : qui fait quoi, pour quand, avec quelle validation.","kind":"document"},{"slug":"competence","title":"Compétence","definition":"Capacité à mobiliser connaissances, savoir-faire et comportements pour réussir une activité professionnelle.","kind":"notion"},{"slug":"concession","title":"Concession","definition":"Modification d’une demande ou d’une position acceptée pendant une négociation, idéalement en échange d’une contrepartie.","kind":"notion"},{"slug":"concurrent","title":"Concurrent","definition":"Organisation proposant une solution comparable ou substituable au même besoin dans le périmètre étudié.","kind":"notion"},{"slug":"conditions-contractuelles","title":"Conditions contractuelles","definition":"Règles qui encadrent l’engagement : prix, délais, paiement, livraison, garanties, responsabilités ou autres obligations.","kind":"regle"},{"slug":"confidentialite-integrite-disponibilite","title":"Confidentialité / intégrité / disponibilité","definition":"Trois propriétés de sécurité : empêcher l’accès non autorisé, préserver l’exactitude des données et maintenir leur accessibilité.","kind":"notion"},{"slug":"confidentialite-rh","title":"Confidentialité RH","definition":"Principe de limitation de la diffusion des informations de santé, rémunération et situation personnelle.","kind":"regle"},{"slug":"confinement","title":"Confinement","definition":"Mesures immédiates destinées à limiter l’extension d’un incident avant le retour à la normale.","kind":"notion"},{"slug":"conflit","title":"Conflit","definition":"Opposition persistante entre acteurs sur des intérêts, objectifs, perceptions ou comportements.","kind":"notion"},{"slug":"connaissance-critique","title":"Connaissance critique","definition":"Information, savoir-faire ou repère dont la perte ou l’indisponibilité pourrait fortement perturber l’activité.","kind":"notion"},{"slug":"consommation","title":"Consommation","definition":"Quantité utilisée ou vendue sur une période ; elle aide à estimer le rythme de sortie.","kind":"notion"},{"slug":"consequence","title":"Conséquence","definition":"Dommage ou effet possible pour les personnes, les biens, l’activité, les données ou la conformité.","kind":"notion"},{"slug":"contexte-utile","title":"Contexte utile","definition":"Informations minimales nécessaires pour comprendre la demande sans noyer le destinataire dans des détails inutiles.","kind":"notion"},{"slug":"contrainte-dure","title":"Contrainte dure","definition":"Condition qui ne peut pas être violée : indisponibilité, compétence obligatoire, horaire imposé, durée incompressible, etc.","kind":"notion"},{"slug":"contrainte-souple","title":"Contrainte souple","definition":"Préférence à respecter si possible mais qui peut être arbitrée : ordre souhaité, confort, optimisation du trajet, etc.","kind":"notion"},{"slug":"contrat-de-travail","title":"Contrat de travail","definition":"Accord encadrant la relation de travail et ses éléments essentiels ; sa forme et ses mentions dépendent de la situation.","kind":"document"},{"slug":"controle-commande-reception-facture","title":"Contrôle commande-réception-facture","definition":"Rapprochement des trois étapes pour détecter écarts de quantité, prix, référence ou condition avant règlement.","kind":"methode"},{"slug":"controle-de-coherence","title":"Contrôle de cohérence","definition":"Vérification que les données du bulletin correspondent au contrat, aux variables validées et aux règles applicables.","kind":"methode"},{"slug":"controle-de-saisie","title":"Contrôle de saisie","definition":"Règle ou vérification destinée à empêcher ou repérer une donnée impossible, incomplète ou incohérente au moment de la saisie.","kind":"methode"},{"slug":"convention-collective","title":"Convention collective","definition":"Texte négocié au niveau d’une branche qui complète les règles légales pour les entreprises et salariés relevant de son champ.","kind":"regle"},{"slug":"correction","title":"Correction","definition":"Action qui traite le problème constaté immédiatement sans forcément supprimer sa cause.","kind":"methode"},{"slug":"correlation-cause","title":"Corrélation / cause","definition":"Deux phénomènes peuvent évoluer ensemble sans que l’un soit nécessairement la cause de l’autre.","kind":"notion"},{"slug":"cout-complet","title":"Coût complet","definition":"Coût intégrant l’ensemble des charges affectées à l’objet selon la méthode retenue.","kind":"indicateur"},{"slug":"cout-direct","title":"Coût direct","definition":"Dépense directement facturée ou liée à l’action : prix pédagogique, déplacement, hébergement, etc. selon le cas.","kind":"indicateur"},{"slug":"cout-global-de-financement","title":"Coût global de financement","definition":"Ensemble des flux, frais, intérêts, loyers, garanties et impacts de trésorerie pertinents selon la solution comparée.","kind":"indicateur"},{"slug":"cout-indirect","title":"Coût indirect","definition":"Coût lié notamment au temps mobilisé, au remplacement ou à l’organisation ; il doit être défini selon la méthode retenue par la PME.","kind":"indicateur"},{"slug":"cout-total","title":"Coût total","definition":"Ensemble des coûts liés à l’offre, pas seulement le prix affiché : options, transport, maintenance, consommables, délais, etc. selon le besoin.","kind":"indicateur"},{"slug":"criticite","title":"Criticité","definition":"Résultat d’une méthode de combinaison des critères de probabilité/fréquence et de gravité pour hiérarchiser.","kind":"indicateur"},{"slug":"critere-de-choix","title":"Critère de choix","definition":"Élément utilisé pour comparer les offres : coût, délai, qualité, service, conformité, risque, etc.","kind":"notion"},{"slug":"critere-de-ciblage","title":"Critère de ciblage","definition":"Caractéristique utilisée pour inclure ou exclure un prospect : secteur, taille, zone, besoin, équipement, comportement, etc.","kind":"notion"},{"slug":"critere-de-selection","title":"Critère de sélection","definition":"Élément observable ou vérifiable utilisé pour comparer les candidatures par rapport au besoin.","kind":"methode"},{"slug":"critere-discriminatoire","title":"Critère discriminatoire","definition":"Critère de décision fondé sur un motif interdit et sans lien légitime avec l’emploi ; il ne doit pas entrer dans la sélection.","kind":"regle"},{"slug":"critere-d-attribution","title":"Critère d’attribution","definition":"Élément annoncé par l’acheteur pour comparer les offres recevables, par exemple le prix, la valeur technique ou un délai.","kind":"regle"},{"slug":"critere-d-evaluation","title":"Critère d’évaluation","definition":"Repère défini à l’avance permettant d’apprécier une activité ou un résultat de façon aussi objective que possible.","kind":"methode"},{"slug":"critere-eliminatoire","title":"Critère éliminatoire","definition":"Exigence obligatoire : une offre qui ne la respecte pas ne peut pas être retenue, même si elle est avantageuse sur d’autres points.","kind":"regle"},{"slug":"creance-client","title":"Créance client","definition":"Somme que le client doit à la PME au titre d’une opération justifiée.","kind":"notion"},{"slug":"credit-documentaire","title":"Crédit documentaire","definition":"Mécanisme bancaire dans lequel le paiement dépend de la présentation de documents conformes aux conditions prévues.","kind":"notion"},{"slug":"credit-bail-location-financiere","title":"Crédit-bail / location financière","definition":"Mode de financement ou d’usage d’un actif fondé sur des loyers et conditions contractuelles spécifiques ; la comparaison doit porter sur le besoin réel et le coût/risque global.","kind":"notion"},{"slug":"cse","title":"CSE","definition":"Comité social et économique, instance représentative du personnel mise en place selon les conditions prévues par le droit du travail.","kind":"regle"},{"slug":"danger","title":"Danger","definition":"Propriété ou situation susceptible de causer un dommage.","kind":"notion"},{"slug":"danger-source-de-risque","title":"Danger / source de risque","definition":"Élément ou situation susceptible de provoquer un dommage.","kind":"notion"},{"slug":"date-de-cloture-paie","title":"Date de clôture paie","definition":"Moment interne après lequel une information tardive peut nécessiter une régularisation selon l’organisation.","kind":"notion"},{"slug":"date-d-effet","title":"Date d’effet","definition":"Date à partir de laquelle une règle ou une modification devient applicable.","kind":"regle"},{"slug":"demande-client","title":"Demande client","definition":"Question, besoin ou problème exprimé par un client et qu’il faut qualifier avant de répondre.","kind":"notion"},{"slug":"demande-de-formation","title":"Demande de formation","definition":"Souhait exprimé par un salarié ou un responsable ; il doit être rapproché du besoin professionnel et des priorités de la PME.","kind":"notion"},{"slug":"demande-explicite","title":"Demande explicite","definition":"Action précise attendue du destinataire, formulée de façon visible et compréhensible.","kind":"methode"},{"slug":"destinataire-rgpd","title":"Destinataire (RGPD)","definition":"Personne, service ou organisme auquel des données personnelles sont communiquées ou rendues accessibles.","kind":"regle"},{"slug":"destinataire-autorise","title":"Destinataire autorisé","definition":"Personne ou organisme qui peut recevoir une information parce que sa fonction, la règle applicable ou la procédure le justifie.","kind":"regle"},{"slug":"devis","title":"Devis","definition":"Proposition chiffrée qui décrit une prestation, un prix et des conditions ; son acceptation peut engager les parties selon la situation.","kind":"document"},{"slug":"devis-accepte","title":"Devis accepté","definition":"Proposition commerciale devenue référence de l’accord lorsqu’elle est valablement acceptée selon le contexte.","kind":"document"},{"slug":"dialogue-social","title":"Dialogue social","definition":"Échanges organisés entre direction et représentants/salariés sur les sujets relevant de leurs rôles respectifs.","kind":"notion"},{"slug":"documents-de-fin-de-contrat","title":"Documents de fin de contrat","definition":"Documents que l’employeur doit préparer ou remettre au salarié lors de la fin du contrat selon la situation applicable.","kind":"document"},{"slug":"donnee-information-document","title":"Donnée / information / document","definition":"Une donnée est un élément brut ; une information est une donnée interprétée dans un contexte ; un document organise et conserve des informations.","kind":"notion"},{"slug":"donnee-brute","title":"Donnée brute","definition":"Valeur issue d’une source : jours d’absence, effectif, heures prévues, etc.","kind":"notion"},{"slug":"donnee-de-facturation","title":"Donnée de facturation","definition":"Information nécessaire pour identifier les parties, décrire l’opération, calculer les montants et transmettre correctement une facture.","kind":"notion"},{"slug":"donnee-de-paie","title":"Donnée de paie","definition":"Information individuelle ou collective utilisée pour calculer, contrôler ou déclarer la paie d’une période.","kind":"notion"},{"slug":"donnee-de-reference","title":"Donnée de référence","definition":"Donnée de base utilisée par plusieurs opérations du système d’information, par exemple une identité, une adresse ou une condition de paiement.","kind":"notion"},{"slug":"donnee-de-sante","title":"Donnée de santé","definition":"Donnée personnelle relative à la santé physique ou mentale d’une personne ; elle appartient aux catégories sensibles.","kind":"notion"},{"slug":"donnee-personnelle","title":"Donnée personnelle","definition":"Information se rapportant à une personne physique identifiée ou identifiable.","kind":"notion"},{"slug":"donnee-rh-confidentielle","title":"Donnée RH confidentielle","definition":"Information personnelle ou professionnelle dont l’accès doit être limité aux personnes qui en ont besoin pour leur mission.","kind":"notion"},{"slug":"donnee-sensible","title":"Donnée sensible","definition":"Catégorie de donnée personnelle bénéficiant d’une protection renforcée, notamment les données de santé.","kind":"notion"},{"slug":"dossier-de-consultation","title":"Dossier de consultation","definition":"Ensemble des documents fournis par l’acheteur qui décrivent le besoin, les règles de la consultation, les pièces attendues, les critères et les délais.","kind":"document"},{"slug":"dossier-du-personnel","title":"Dossier du personnel","definition":"Ensemble organisé des informations et documents nécessaires au suivi administratif du salarié.","kind":"document"},{"slug":"doublon","title":"Doublon","definition":"Enregistrement créé plusieurs fois pour une même personne, entreprise ou opération, ce qui peut produire des incohérences.","kind":"notion"},{"slug":"dpae","title":"DPAE","definition":"Déclaration préalable à l’embauche réalisée par l’employeur auprès de l’organisme compétent avant l’embauche selon les règles en vigueur.","kind":"document"},{"slug":"dpo-dpd","title":"DPO / DPD","definition":"Délégué à la protection des données : personne chargée notamment d’informer, conseiller et accompagner la conformité ; sa désignation n’est obligatoire que dans certains cas.","kind":"regle"},{"slug":"droit-d-acces","title":"Droit d’accès","definition":"Autorisation donnée selon le rôle pour consulter, modifier, partager ou administrer une ressource.","kind":"regle"},{"slug":"dsn","title":"DSN","definition":"Déclaration sociale nominative transmise à partir des données de paie pour déclarer de nombreuses informations sociales aux organismes concernés.","kind":"document"},{"slug":"duerp","title":"DUERP","definition":"Document unique dans lequel l’employeur transcrit et met à jour les résultats de l’évaluation des risques professionnels.","kind":"document"},{"slug":"dume","title":"DUME","definition":"Document unique de marché européen : déclaration sur l’honneur standardisée permettant de présenter certaines informations de candidature à un marché public.","kind":"document"},{"slug":"dysfonctionnement","title":"Dysfonctionnement","definition":"Écart de fonctionnement par rapport à ce qui est prévu ou attendu.","kind":"notion"},{"slug":"decaissement","title":"Décaissement","definition":"Sortie réelle ou prévue de trésorerie à une date donnée.","kind":"notion"},{"slug":"decalage-de-tresorerie","title":"Décalage de trésorerie","definition":"Différence de calendrier entre les encaissements et les décaissements, même lorsque l’activité peut être rentable.","kind":"notion"},{"slug":"decision-de-reunion","title":"Décision de réunion","definition":"Choix acté avec responsable, action et échéance ; il doit être traçable.","kind":"document"},{"slug":"declaration-de-sinistre","title":"Déclaration de sinistre","definition":"Transmission structurée des faits et pièces à l’assureur selon le contrat et la procédure de la PME.","kind":"methode"},{"slug":"delai-d-approvisionnement","title":"Délai d’approvisionnement","definition":"Temps entre le déclenchement d’une commande et la disponibilité effective des articles.","kind":"notion"},{"slug":"dependance","title":"Dépendance","definition":"Lien entre deux tâches lorsque l’une ne peut commencer ou finir qu’après une autre.","kind":"notion"},{"slug":"detection-recuperation","title":"Détection / récupération","definition":"Mesure permettant de repérer plus vite un événement ou de rétablir l’activité après celui-ci.","kind":"methode"},{"slug":"e-reputation","title":"E-réputation","definition":"Image de l’entreprise visible et construite sur internet et les plateformes numériques.","kind":"notion"},{"slug":"efficacite-d-une-mesure","title":"Efficacité d’une mesure","definition":"Capacité démontrée d’une mesure à réduire la probabilité, l’exposition ou les conséquences du risque ; son existence seule ne suffit pas.","kind":"notion"},{"slug":"emprunt","title":"Emprunt","definition":"Financement par dette remboursée selon un échéancier avec coût financier et conditions contractuelles.","kind":"notion"},{"slug":"encaissement","title":"Encaissement","definition":"Entrée réelle ou prévue de trésorerie à une date donnée.","kind":"notion"},{"slug":"encours-client","title":"Encours client","definition":"Montant total des sommes dues ou du crédit accordé à un client à un moment donné.","kind":"indicateur"},{"slug":"enjeu","title":"Enjeu","definition":"Conséquence possible de la communication pour la relation, l’activité, l’image, le délai ou la décision.","kind":"notion"},{"slug":"enregistrement","title":"Enregistrement","definition":"Ensemble des champs décrivant une même unité, par exemple un client, une facture ou une intervention.","kind":"notion"},{"slug":"entretien-annuel-d-evaluation","title":"Entretien annuel d’évaluation","definition":"Entretien de management utilisé pour faire le point sur l’activité, les résultats, les objectifs ou les besoins selon les pratiques de l’organisation.","kind":"methode"},{"slug":"entretien-de-parcours-professionnel","title":"Entretien de parcours professionnel","definition":"Entretien consacré au parcours et aux perspectives professionnelles du salarié selon le cadre légal et les règles applicables au moment où il est organisé.","kind":"regle"},{"slug":"esn","title":"ESN","definition":"Entreprise de services du numérique pouvant accompagner la PME sur son système d’information.","kind":"notion"},{"slug":"exclusion","title":"Exclusion","definition":"Situation ou dommage que le contrat prévoit de ne pas couvrir.","kind":"notion"},{"slug":"exposition","title":"Exposition","definition":"Situation dans laquelle un salarié peut être en contact avec le danger dans son activité réelle.","kind":"notion"},{"slug":"ecart","title":"Écart","definition":"Différence entre valeur réelle et référence : objectif, budget, période précédente ou autre base définie.","kind":"indicateur"},{"slug":"ecart-projet","title":"Écart projet","definition":"Différence entre ce qui était prévu et ce qui est réellement constaté sur délai, coût, ressource, qualité ou contenu.","kind":"indicateur"},{"slug":"echeance-de-paiement","title":"Échéance de paiement","definition":"Date à partir de laquelle le règlement attendu devient exigible selon les conditions prévues.","kind":"regle"},{"slug":"echeance-daction","title":"Échéance d’action","definition":"Date ou délai dans lequel une réponse ou une action est attendue lorsqu’il existe.","kind":"notion"},{"slug":"echeance","title":"Échéance — préciser le sens","definition":"Une échéance est une date ou un délai à respecter. Précisez s’il s’agit d’une échéance de paiement ou d’une échéance d’action.","kind":"regle"},{"slug":"electeur-eligible","title":"Électeur / éligible","definition":"Un salarié peut avoir le droit de voter et, selon les conditions applicables, être ou non candidat.","kind":"regle"},{"slug":"evaluation-de-la-formation","title":"Évaluation de la formation","definition":"Vérification de la réalisation, des acquis et, si possible, de leur transfert ou utilité dans le travail.","kind":"methode"},{"slug":"evolution","title":"Évolution","definition":"Comparaison dans le temps qui nécessite des périodes et définitions comparables.","kind":"notion"},{"slug":"evenement-professionnel","title":"Événement professionnel","definition":"Action organisée dans un objectif professionnel, avec des participants, des contraintes, des moyens et un calendrier.","kind":"notion"},{"slug":"facture","title":"Facture","definition":"Document qui constate une vente et détaille les sommes dues ainsi que les mentions obligatoires.","kind":"document"},{"slug":"facture-electronique","title":"Facture électronique","definition":"Facture émise, transmise et reçue sous forme électronique selon le dispositif et les formats prévus par la réglementation applicable.","kind":"regle"},{"slug":"fait-interpretation","title":"Fait / interprétation","definition":"Le fait est observable ou vérifiable ; l’interprétation est le sens que l’on lui attribue.","kind":"notion"},{"slug":"fait-opinion","title":"Fait / opinion","definition":"Un fait peut être vérifié par une pièce ou une observation ; une opinion exprime une perception ou un jugement.","kind":"notion"},{"slug":"fait-de-facturation","title":"Fait de facturation","definition":"Événement qui permet ou impose d’établir la facture selon la nature de l’opération, le contrat et la règle applicable.","kind":"regle"},{"slug":"fiabilite","title":"Fiabilité","definition":"Degré de confiance que l’on peut accorder à une source en fonction de son auteur, sa date, son objectif et sa traçabilité.","kind":"notion"},{"slug":"fiche-de-poste","title":"Fiche de poste","definition":"Document qui décrit la finalité, les missions, activités et compétences attendues d’un poste.","kind":"document"},{"slug":"fidelisation","title":"Fidélisation","definition":"Actions destinées à conserver et développer la relation avec les clients existants.","kind":"methode"},{"slug":"filtre","title":"Filtre","definition":"Fonction qui affiche uniquement les lignes répondant à un ou plusieurs critères sans modifier les données d’origine.","kind":"outil"},{"slug":"fin-de-contrat","title":"Fin de contrat","definition":"Événement mettant fin à la relation de travail selon un motif, une date et des formalités qui dépendent de la situation.","kind":"notion"},{"slug":"finalite-rgpd","title":"Finalité (RGPD)","definition":"Objectif déterminé pour lequel des données personnelles sont utilisées.","kind":"regle"},{"slug":"flux","title":"Flux","definition":"Quantité mesurable qui entre, sort ou est consommée sur une période : kWh, litres, kilogrammes, kilomètres, etc.","kind":"notion"},{"slug":"flux-d-information","title":"Flux d’information","definition":"Circulation d’une information entre acteurs, outils ou étapes d’un processus.","kind":"notion"},{"slug":"franchise","title":"Franchise","definition":"Part du dommage qui reste à la charge de l’assuré lorsque la garantie joue, selon le contrat.","kind":"notion"},{"slug":"frng","title":"FRNG","definition":"Ressource durable disponible après financement des emplois stables dans l’analyse fonctionnelle.","kind":"indicateur"},{"slug":"garantie","title":"Garantie","definition":"Risque ou type de dommage pris en charge par le contrat dans les conditions prévues.","kind":"notion"},{"slug":"geste-commercial","title":"Geste commercial","definition":"Avantage accordé au client ; il doit respecter les règles de délégation et ne vaut pas automatiquement reconnaissance juridique de responsabilité.","kind":"notion"},{"slug":"gravite","title":"Gravité","definition":"Importance de la conséquence si l’événement survient.","kind":"indicateur"},{"slug":"grille-d-entretien","title":"Grille d’entretien","definition":"Support commun qui structure les questions, critères et traces afin de comparer les candidats de manière cohérente.","kind":"document"},{"slug":"habilitation","title":"Habilitation","definition":"Droit accordé à un utilisateur pour accéder à des données ou fonctions nécessaires à son rôle.","kind":"regle"},{"slug":"hameconnage-phishing","title":"Hameçonnage / phishing","definition":"Message frauduleux visant à obtenir une action, un mot de passe, un paiement ou l’ouverture d’un contenu malveillant.","kind":"notion"},{"slug":"heures-supplementaires","title":"Heures supplémentaires","definition":"Heures effectuées au-delà de la durée de référence applicable et qui doivent être identifiées et traitées selon les règles en vigueur.","kind":"regle"},{"slug":"ht-tva-ttc","title":"HT / TVA / TTC","definition":"HT est le montant hors taxe ; la TVA est la taxe calculée selon le régime applicable ; TTC est le total facturé taxe comprise.","kind":"regle"},{"slug":"hypothese-budgetaire","title":"Hypothèse budgétaire","definition":"Hypothèse explicite utilisée pour construire un budget, par exemple un volume, un prix, un taux ou une évolution attendue.","kind":"notion"},{"slug":"identifiant","title":"Identifiant","definition":"Valeur permettant de distinguer de façon fiable un enregistrement des autres.","kind":"notion"},{"slug":"identite-de-marque-image","title":"Identité de marque / image","definition":"L’identité correspond à ce que l’entreprise veut exprimer ; l’image est la perception produite auprès des publics.","kind":"notion"},{"slug":"identite-numerique","title":"Identité numérique","definition":"Traces, contenus et représentations de l’entreprise dans les environnements numériques.","kind":"notion"},{"slug":"immobilisation","title":"Immobilisation","definition":"Bien ou droit destiné à servir durablement l’activité de l’entreprise.","kind":"notion"},{"slug":"impact-environnemental","title":"Impact environnemental","definition":"Conséquence de cet aspect sur l’environnement.","kind":"notion"},{"slug":"impact-operationnel","title":"Impact opérationnel","definition":"Conséquence concrète de l’information sur les documents, procédures, outils, responsabilités ou échéances de la PME.","kind":"notion"},{"slug":"impaye","title":"Impayé","definition":"Somme arrivée à échéance mais qui n’a pas été réglée.","kind":"notion"},{"slug":"indexation","title":"Indexation","definition":"Attribution de métadonnées ou critères facilitant la recherche et le classement.","kind":"methode"},{"slug":"indicateur","title":"Indicateur","definition":"Mesure définie de façon stable pour objectiver une situation, suivre un objectif, un risque, une activité ou une performance.","kind":"indicateur"},{"slug":"indicateur-de-communication","title":"Indicateur de communication","definition":"Mesure permettant d’apprécier portée, engagement, trafic, demandes, conversion ou autre effet lié à l’objectif.","kind":"indicateur"},{"slug":"indicateur-d-efficacite","title":"Indicateur d’efficacité","definition":"Mesure permettant de vérifier après action si le dysfonctionnement a réellement diminué ou disparu.","kind":"indicateur"},{"slug":"integration","title":"Intégration","definition":"Période organisée permettant à un nouveau salarié de comprendre son poste, son environnement, ses interlocuteurs et les règles de fonctionnement.","kind":"methode"},{"slug":"jalon","title":"Jalon","definition":"Point de contrôle ou résultat intermédiaire important permettant de vérifier l’avancement.","kind":"notion"},{"slug":"justificatif","title":"Justificatif","definition":"Document ou information permettant d’établir le motif, la période et les droits associés à l’absence.","kind":"document"},{"slug":"kpi","title":"KPI","definition":"Indicateur jugé particulièrement important pour un objectif donné ; tous les chiffres d’un tableau de bord ne sont pas des KPI.","kind":"indicateur"},{"slug":"lettrage","title":"Lettrage","definition":"Rapprochement entre factures, avoirs et règlements afin d’identifier ce qui reste réellement ouvert.","kind":"methode"},{"slug":"liste-electorale","title":"Liste électorale","definition":"Liste des salariés admis à participer au vote dans le collège concerné selon les règles applicables.","kind":"document"},{"slug":"litige","title":"Litige","definition":"Désaccord portant sur la facture, la livraison ou la prestation ; il doit être distingué d’un simple retard de paiement.","kind":"notion"},{"slug":"livrable","title":"Livrable","definition":"Résultat concret qui doit être remis ou validé à une étape ou à la fin du projet.","kind":"notion"},{"slug":"marche","title":"Marché","definition":"Ensemble des offres, demandes et acteurs autour d’un produit ou service dans un périmètre défini.","kind":"notion"},{"slug":"marche-public","title":"Marché public","definition":"Contrat conclu par un acheteur public avec un opérateur économique pour répondre à un besoin de travaux, fournitures ou services.","kind":"notion"},{"slug":"marge-de-negociation","title":"Marge de négociation","definition":"Espace compris entre l’objectif recherché et la limite à ne pas dépasser sans nouvelle validation.","kind":"notion"},{"slug":"marge-sur-cout-variable","title":"Marge sur coût variable","definition":"Différence entre chiffre d’affaires et charges variables ; elle contribue à couvrir les charges fixes puis le résultat.","kind":"indicateur"},{"slug":"matrice-de-criticite","title":"Matrice de criticité","definition":"Outil qui aide à comparer et hiérarchiser plusieurs risques selon une règle commune.","kind":"methode"},{"slug":"message","title":"Message","definition":"Idée essentielle à faire comprendre ou retenir ; elle doit rester cohérente avec la stratégie et l’identité de la PME.","kind":"notion"},{"slug":"mesure-de-prevention","title":"Mesure de prévention","definition":"Action visant à supprimer ou réduire le risque en agissant sur la situation de travail, l’organisation, la protection ou l’information.","kind":"methode"},{"slug":"mesure-existante","title":"Mesure existante","definition":"Protection ou contrôle déjà en place ; elle doit être prise en compte avant de proposer une nouvelle action.","kind":"notion"},{"slug":"mise-en-service","title":"Mise en service","definition":"Moment où un équipement ou une immobilisation devient effectivement disponible pour l’usage prévu.","kind":"notion"},{"slug":"mission-activite-tache","title":"Mission / activité / tâche","definition":"La mission exprime une responsabilité globale ; l’activité regroupe des travaux ; la tâche décrit une action concrète.","kind":"notion"},{"slug":"mode-operatoire","title":"Mode opératoire","definition":"Document opérationnel qui décrit, dans un ordre utilisable, comment réaliser une tâche ou une opération afin qu’elle puisse être reproduite de manière cohérente.","kind":"document"},{"slug":"niveau-de-confidentialite","title":"Niveau de confidentialité","definition":"Degré de sensibilité d’une information qui détermine qui peut la recevoir, par quel canal et avec quelles précautions.","kind":"notion"},{"slug":"nommage","title":"Nommage","definition":"Règle commune pour nommer les fichiers afin d’identifier contenu, date, version ou statut.","kind":"methode"},{"slug":"non-conformite","title":"Non-conformité","definition":"Écart entre ce qui était prévu ou attendu et ce qui a réellement été livré ou réalisé.","kind":"notion"},{"slug":"note-de-decision","title":"Note de décision","definition":"Document court qui présente des faits, une analyse, des options et une recommandation afin d’aider un responsable à décider.","kind":"document"},{"slug":"numerateur-denominateur","title":"Numérateur / dénominateur","definition":"Éléments d’un ratio : la valeur étudiée et la base à laquelle elle est rapportée.","kind":"indicateur"},{"slug":"negociation","title":"Négociation","definition":"Échange préparé entre des parties ayant des intérêts partiellement différents afin de rechercher un accord acceptable.","kind":"methode"},{"slug":"objectif","title":"Objectif","definition":"Résultat attendu auquel l’indicateur doit être relié pour avoir un sens.","kind":"notion"},{"slug":"objectif-de-communication","title":"Objectif de communication","definition":"Effet concret recherché par une communication : informer, obtenir une réponse, rassurer, faire connaître, engager ou faire agir.","kind":"notion"},{"slug":"objectif-de-formation","title":"Objectif de formation","definition":"Capacité concrète que la personne doit pouvoir mobiliser après la formation.","kind":"notion"},{"slug":"objet-du-courriel","title":"Objet du courriel","definition":"Formulation courte qui permet au destinataire d’identifier immédiatement le sujet et, si utile, l’action attendue.","kind":"notion"},{"slug":"obligation-recommandation","title":"Obligation / recommandation","definition":"Une obligation s’impose dans son champ d’application ; une recommandation guide l’action sans avoir nécessairement le même caractère contraignant.","kind":"regle"},{"slug":"observation-factuelle","title":"Observation factuelle","definition":"Description de ce qui est réellement vu ou documenté, sans se présenter comme expert lorsqu’une expertise technique est nécessaire.","kind":"notion"},{"slug":"opco","title":"OPCO","definition":"Opérateur de compétences susceptible d’accompagner les entreprises relevant de son champ, notamment sur certains financements et services.","kind":"notion"},{"slug":"operation-en-circulation","title":"Opération en circulation","definition":"Opération enregistrée d’un côté mais pas encore apparue de l’autre : chèque, virement, frais, remise, etc.","kind":"notion"},{"slug":"ordre-du-jour","title":"Ordre du jour","definition":"Liste structurée des sujets à traiter pendant une réunion, avec un objectif et un temps disponible.","kind":"document"},{"slug":"orientation","title":"Orientation","definition":"Fait de diriger une demande vers la personne, le service ou le processus capable de la traiter correctement.","kind":"notion"},{"slug":"parcours-d-integration","title":"Parcours d’intégration","definition":"Suite planifiée d’actions, informations, rencontres et contrôles destinés à rendre l’arrivée d’un salarié opérationnelle et sécurisée.","kind":"methode"},{"slug":"performance-fournisseur","title":"Performance fournisseur","definition":"Capacité d’un fournisseur à respecter dans la durée les critères attendus : qualité, délai, coût, service, conformité ou fiabilité.","kind":"indicateur"},{"slug":"pgi","title":"PGI","definition":"Progiciel de gestion intégré : logiciel qui centralise plusieurs fonctions et données de gestion.  Dans cette bibliothèque, Odoo sert d’exemple de PGI pour les mises en pratique.","kind":"outil"},{"slug":"piece-jointe","title":"Pièce jointe","definition":"Document nécessaire à la compréhension ou à l’action ; sa présence et sa bonne version doivent être vérifiées avant l’envoi.","kind":"document"},{"slug":"piece-justificative","title":"Pièce justificative","definition":"Document qui prouve et explique l’opération comptable : facture, relevé, avis, reçu, etc.","kind":"document"},{"slug":"plafond","title":"Plafond","definition":"Limite maximale d’indemnisation prévue par le contrat pour une garantie donnée.","kind":"notion"},{"slug":"plan-de-financement","title":"Plan de financement","definition":"Tableau mettant en regard besoins durables et ressources prévues afin de vérifier la cohérence financière d’un projet.","kind":"document"},{"slug":"plateforme-agreee","title":"Plateforme agréée","definition":"Plateforme reconnue par l’administration pour assurer les fonctions prévues par le dispositif de facturation électronique.","kind":"outil"},{"slug":"ponderation","title":"Pondération","definition":"Importance relative attribuée à chaque critère dans une comparaison multicritère.","kind":"indicateur"},{"slug":"preuve-de-competence","title":"Preuve de compétence","definition":"Élément concret du CV, de l’expérience, d’un test ou de l’entretien permettant d’étayer l’évaluation.","kind":"document"},{"slug":"preuve-de-conformite","title":"Preuve de conformité","definition":"Élément vérifiable permettant de montrer qu’une exigence définie est respectée.","kind":"notion"},{"slug":"preuve-de-depot","title":"Preuve de dépôt","definition":"Trace horodatée ou accusé confirmant qu’un dossier a bien été transmis avant l’échéance prévue.","kind":"document"},{"slug":"preuve-du-dommage","title":"Preuve du dommage","definition":"Pièce permettant d’établir existence, cause, date, valeur ou étendue du dommage : photos, factures, devis, constat, etc.","kind":"document"},{"slug":"preuve-d-execution","title":"Preuve d’exécution","definition":"Document ou information montrant que le bien a été livré ou le service réalisé : bon de livraison, réception, validation, etc.","kind":"document"},{"slug":"preuve-d-evaluation","title":"Preuve d’évaluation","definition":"Élément du dossier ou source identifiable qui justifie un critère, une note ou une conclusion sur le risque.","kind":"document"},{"slug":"principe-du-moindre-privilege","title":"Principe du moindre privilège","definition":"Principe consistant à n’accorder à un utilisateur que les droits nécessaires à ses missions, pendant la durée nécessaire.","kind":"regle"},{"slug":"priorite","title":"Priorité","definition":"Ordre de traitement fondé sur des critères définis : sécurité, engagement client, urgence, impact, dépendance, etc.","kind":"notion"},{"slug":"probabilite-frequence","title":"Probabilité / fréquence","definition":"Appréciation de la possibilité ou de la répétition de l’événement selon l’échelle choisie.","kind":"indicateur"},{"slug":"processus","title":"Processus","definition":"Enchaînement d’activités reliées qui transforme des éléments d’entrée en un résultat pour un destinataire interne ou externe.","kind":"notion"},{"slug":"procedure","title":"Procédure","definition":"Description structurée des étapes, rôles, contrôles et traces attendues pour une activité.","kind":"methode"},{"slug":"proposition-commerciale","title":"Proposition commerciale","definition":"Action argumentée reliant diagnostic, cible, objectif, moyens et indicateurs.","kind":"document"},{"slug":"propriete-intellectuelle","title":"Propriété intellectuelle","definition":"Ensemble de droits qui peuvent protéger certaines créations, signes distinctifs, inventions ou œuvres selon des conditions précises.","kind":"regle"},{"slug":"prospect","title":"Prospect","definition":"Organisation ou personne susceptible de devenir cliente, mais qui ne l’est pas encore.","kind":"notion"},{"slug":"protection","title":"Protection","definition":"Mesure qui vise surtout à limiter les conséquences lorsque l’événement survient.","kind":"methode"},{"slug":"protocole-preelectoral","title":"Protocole préélectoral","definition":"Accord ou document préparatoire encadrant certaines modalités de l’élection dans les conditions prévues par la réglementation.","kind":"document"},{"slug":"prevention","title":"Prévention","definition":"Mesure qui agit en amont pour supprimer une cause ou réduire la probabilité / l’exposition.","kind":"methode"},{"slug":"perimetre-de-lindicateur","title":"Périmètre de l’indicateur","definition":"Population, établissement, service, catégorie ou période réellement inclus dans le calcul.","kind":"notion"},{"slug":"perimetre-de-prestation","title":"Périmètre de prestation","definition":"Ce qui est inclus, exclu ou limité dans la solution proposée au client.","kind":"notion"},{"slug":"perimetre-du-projet","title":"Périmètre du projet","definition":"Ce qui est inclus et exclu du projet afin d’éviter les attentes implicites.","kind":"notion"},{"slug":"perimetre","title":"Périmètre — préciser le sens","definition":"Le périmètre désigne ce qui est inclus dans une analyse. Précisez s’il s’agit du périmètre d’un projet ou de celui d’un indicateur.","kind":"notion"},{"slug":"periode-de-paie","title":"Période de paie","definition":"Période à laquelle les éléments collectés doivent être rattachés pour calculer et contrôler le bulletin.","kind":"notion"},{"slug":"qualification","title":"Qualification","definition":"Vérification et enrichissement des données pour savoir si un contact est exploitable et prioritaire.","kind":"methode"},{"slug":"qualification-d-un-prospect","title":"Qualification d’un prospect","definition":"Vérification qu’un prospect correspond réellement à la cible et présente un potentiel exploitable.","kind":"methode"},{"slug":"qualification-fournisseur","title":"Qualification fournisseur","definition":"Vérification qu’un fournisseur répond aux exigences nécessaires pour être consulté ou retenu.","kind":"methode"},{"slug":"qualite-des-donnees","title":"Qualité des données","definition":"Degré auquel des données sont exactes, complètes, cohérentes, à jour et adaptées à l’usage prévu.","kind":"notion"},{"slug":"question-ouverte","title":"Question ouverte","definition":"Question qui invite l’interlocuteur à développer une réponse plutôt qu’à choisir seulement entre oui et non.","kind":"methode"},{"slug":"rapprochement-bancaire","title":"Rapprochement bancaire","definition":"Comparaison entre relevé bancaire et comptabilité afin d’expliquer les différences et repérer les opérations à enregistrer ou corriger.","kind":"methode"},{"slug":"ratio-financier","title":"Ratio financier","definition":"Rapport entre deux grandeurs financières choisi pour éclairer une dimension de la situation de l’entreprise.","kind":"indicateur"},{"slug":"recherche-dans-un-tableur","title":"Recherche dans un tableur","definition":"Fonction permettant de retrouver ou ramener une valeur à partir d’un critère ou d’une clé dans un tableau.","kind":"outil"},{"slug":"recommandation","title":"Recommandation","definition":"Proposition argumentée préparée pour aider le décideur ; elle reste distincte de la décision finale.","kind":"notion"},{"slug":"reformulation","title":"Reformulation","definition":"Restitution neutre de ce que l’interlocuteur a exprimé afin de vérifier la compréhension.","kind":"methode"},{"slug":"registre-des-activites-de-traitement","title":"Registre des activités de traitement","definition":"Document qui recense les traitements de données personnelles et en décrit les principales caractéristiques.","kind":"document"},{"slug":"registre-et-ton","title":"Registre et ton","definition":"Façon d’exprimer le message en fonction du destinataire, du contexte et de la relation professionnelle.","kind":"notion"},{"slug":"relance-amiable","title":"Relance amiable","definition":"Action de rappel et de suivi visant à obtenir le paiement sans engager de soi-même une procédure contentieuse.","kind":"methode"},{"slug":"releve-bancaire","title":"Relevé bancaire","definition":"Document émis par la banque retraçant les opérations effectivement passées sur le compte bancaire.","kind":"document"},{"slug":"replanification","title":"Replanification","definition":"Modification maîtrisée du planning avec mise à jour des conséquences, responsables et personnes à informer.","kind":"methode"},{"slug":"responsable-du-traitement","title":"Responsable du traitement","definition":"Organisme ou personne qui détermine les finalités et les moyens essentiels d’un traitement de données personnelles.","kind":"regle"},{"slug":"ressource","title":"Ressource","definition":"Moyen nécessaire à l’intervention : technicien, véhicule, matériel, compétence, créneau, etc.","kind":"notion"},{"slug":"rgpd","title":"RGPD","definition":"Cadre européen de protection des données personnelles et des droits des personnes.","kind":"regle"},{"slug":"risque","title":"Risque","definition":"Combinaison d’un événement possible et de ses conséquences dans le contexte de la PME.","kind":"notion"},{"slug":"risque-client","title":"Risque client","definition":"Risque que le client ne paie pas, paie en retard ou crée une perte financière.","kind":"notion"},{"slug":"risque-de-change","title":"Risque de change","definition":"Risque que la variation d’une devise modifie la valeur en euros d’un paiement, d’une créance ou d’une dette.","kind":"notion"},{"slug":"risque-de-contrepartie","title":"Risque de contrepartie","definition":"Risque que l’autre partie à l’opération n’exécute pas correctement son obligation, notamment le paiement ou la livraison.","kind":"notion"},{"slug":"risque-initial","title":"Risque initial","definition":"Niveau de risque évalué avant de tenir compte des mesures de maîtrise existantes, lorsqu’il est pertinent et possible de le distinguer.","kind":"notion"},{"slug":"risque-professionnel","title":"Risque professionnel","definition":"Possibilité qu’un salarié subisse un dommage en raison de son exposition à un danger au travail.","kind":"notion"},{"slug":"risque-residuel","title":"Risque résiduel","definition":"Niveau de risque qui subsiste après prise en compte des mesures réellement mises en œuvre et de leur efficacité.","kind":"notion"},{"slug":"regle-collaborative","title":"Règle collaborative","definition":"Accord explicite sur rôles, canaux, délais, validation et partage d’information.","kind":"regle"},{"slug":"reclamation","title":"Réclamation","definition":"Expression explicite d’un mécontentement à laquelle le client attend une réponse ou une solution.","kind":"notion"},{"slug":"referent-d-integration","title":"Référent d’intégration","definition":"Personne identifiée pour accompagner le nouveau salarié, répondre aux questions prévues et faciliter la coordination avec les autres acteurs.","kind":"notion"},{"slug":"referentiel-de-certification","title":"Référentiel de certification","definition":"Ensemble des exigences utilisées pour évaluer si une organisation, un produit, un service ou un système répond aux conditions de la certification.","kind":"regle"},{"slug":"satisfaction-client","title":"Satisfaction client","definition":"Appréciation du client sur son expérience ; elle renseigne sur la relation avec la PME mais ne décrit pas à elle seule l’évolution du marché.","kind":"notion"},{"slug":"sauvegarde","title":"Sauvegarde","definition":"Copie destinée à permettre la récupération après incident ; elle ne remplace pas à elle seule une politique d’archivage.","kind":"methode"},{"slug":"sauvegarde-restauration","title":"Sauvegarde / restauration","definition":"Copie protégée permettant de récupérer des données ; sa valeur dépend notamment de sa séparation et de la capacité réelle à restaurer.","kind":"methode"},{"slug":"scenario","title":"Scénario","definition":"Hypothèse cohérente utilisée pour mesurer l’effet d’un changement de délai, montant ou décision sur la trésorerie.","kind":"notion"},{"slug":"segment","title":"Segment","definition":"Sous-ensemble du marché regroupant des clients ou besoins suffisamment homogènes pour être analysés séparément.","kind":"notion"},{"slug":"segmentation","title":"Segmentation","definition":"Regroupement de contacts ayant des caractéristiques communes afin d’adapter l’action commerciale.","kind":"methode"},{"slug":"seuil-de-rentabilite","title":"Seuil de rentabilité","definition":"Niveau d’activité ou de chiffre d’affaires pour lequel le résultat est nul selon les hypothèses du modèle.","kind":"indicateur"},{"slug":"seuil-de-reapprovisionnement","title":"Seuil de réapprovisionnement","definition":"Niveau à partir duquel une commande doit être envisagée selon consommation, délai et sécurité retenue par la PME.","kind":"indicateur"},{"slug":"seuil-d-alerte","title":"Seuil d’alerte","definition":"Valeur ou situation définie à partir de laquelle une attention ou une action est requise.","kind":"indicateur"},{"slug":"si","title":"SI","definition":"Système d’information : ensemble organisé de personnes, données, procédures et outils permettant de faire circuler l’information.","kind":"outil"},{"slug":"signal","title":"Signal","definition":"Information qui mérite d’être vérifiée et croisée avant d’être interprétée comme tendance ou cause.","kind":"notion"},{"slug":"signal-de-veille","title":"Signal de veille","definition":"Information repérée au cours de la veille qui peut annoncer une évolution, un risque ou une opportunité à examiner.","kind":"notion"},{"slug":"simulation","title":"Simulation","definition":"Recalcul d’un résultat en modifiant une hypothèse pour mesurer l’effet possible d’une décision.","kind":"methode"},{"slug":"sinistre","title":"Sinistre","definition":"Événement dommageable susceptible d’être déclaré au titre d’un contrat d’assurance.","kind":"notion"},{"slug":"situation-de-communication","title":"Situation de communication","definition":"Ensemble formé par les acteurs, leurs rôles, l’objectif, le contexte, les enjeux, les contraintes et le canal utilisé.","kind":"notion"},{"slug":"solde-de-conges","title":"Solde de congés","definition":"Nombre de jours ou d’heures de congé acquis, pris et restant à utiliser selon le système de suivi retenu.","kind":"indicateur"},{"slug":"solde-initial-final","title":"Solde initial / final","definition":"Trésorerie disponible au début d’une période puis après prise en compte des flux de la période.","kind":"indicateur"},{"slug":"source-de-droit-social","title":"Source de droit social","definition":"Texte ou accord permettant de connaître la règle applicable : loi, convention collective, accord d’entreprise, contrat, etc., selon le sujet.","kind":"regle"},{"slug":"source-fiable","title":"Source fiable","definition":"Source dont l’auteur, la date, l’objet et le niveau d’autorité permettent d’utiliser l’information avec confiance.","kind":"notion"},{"slug":"source-officielle","title":"Source officielle","definition":"Source publiée par l’autorité compétente pour établir ou expliquer une règle dans son champ de responsabilité.","kind":"regle"},{"slug":"source-primaire","title":"Source primaire","definition":"Source qui publie directement la règle, la décision ou la donnée de référence : texte officiel, administration, organisme compétent.","kind":"regle"},{"slug":"sous-traitant-rgpd","title":"Sous-traitant (RGPD)","definition":"Prestataire qui traite des données personnelles pour le compte du responsable du traitement selon ses instructions.","kind":"regle"},{"slug":"stock-disponible","title":"Stock disponible","definition":"Quantité réellement mobilisable après prise en compte des réservations ou engagements connus.","kind":"indicateur"},{"slug":"stock-physique","title":"Stock physique","definition":"Quantité réellement présente et constatée.","kind":"indicateur"},{"slug":"stock-theorique","title":"Stock théorique","definition":"Quantité enregistrée dans le système après prise en compte des mouvements saisis.","kind":"indicateur"},{"slug":"symptome","title":"Symptôme","definition":"Manifestation visible du problème : erreur, retard, plainte, rejet, retour, etc.","kind":"notion"},{"slug":"systeme-d-information-client","title":"Système d’information client","definition":"Ensemble des données, outils, règles et échanges utilisés pour gérer la relation avec les clients.","kind":"notion"},{"slug":"systeme-d-information-fournisseur","title":"Système d’information fournisseur","definition":"Ensemble des données, outils, règles et historiques utilisés pour gérer la relation avec les fournisseurs.","kind":"notion"},{"slug":"tableau-croise-dynamique-tcd","title":"Tableau croisé dynamique (TCD)","definition":"Outil du tableur qui synthétise rapidement des données selon plusieurs catégories ou dimensions.","kind":"outil"},{"slug":"tableau-de-bord","title":"Tableau de bord","definition":"Sélection structurée d’indicateurs destinée au pilotage ; il doit aider à décider et non accumuler toutes les données disponibles.","kind":"document"},{"slug":"taux","title":"Taux","definition":"Rapport entre deux grandeurs cohérentes, exprimé généralement en pourcentage.","kind":"indicateur"},{"slug":"taux-de-reponse","title":"Taux de réponse","definition":"Part des personnes sollicitées qui ont effectivement répondu à une enquête.","kind":"indicateur"},{"slug":"temps-de-travail-effectif","title":"Temps de travail effectif","definition":"Temps pendant lequel le salarié est à la disposition de l’employeur, suit ses directives et ne peut pas vaquer librement à ses occupations personnelles.","kind":"notion"},{"slug":"tendance","title":"Tendance","definition":"Évolution observée sur plusieurs périodes, points ou sources comparables ; elle ne se déduit pas d’un événement isolé.","kind":"notion"},{"slug":"tension","title":"Tension","definition":"Difficulté relationnelle ou désaccord qui peut gêner le travail sans être encore un conflit ouvert.","kind":"notion"},{"slug":"tension-de-tresorerie","title":"Tension de trésorerie","definition":"Situation dans laquelle les disponibilités prévues deviennent insuffisantes pour faire face aux échéances.","kind":"notion"},{"slug":"test-de-restauration","title":"Test de restauration","definition":"Vérification pratique qu’une sauvegarde peut réellement être récupérée et utilisée dans les conditions prévues.","kind":"methode"},{"slug":"trace-d-entretien","title":"Trace d’entretien","definition":"Document ou enregistrement permettant de conserver les points traités, demandes, décisions ou suites prévues après un entretien.","kind":"document"},{"slug":"traitement-de-donnees","title":"Traitement de données","definition":"Opération ou ensemble d’opérations réalisées sur des données personnelles : collecte, consultation, transmission, conservation, suppression, etc.","kind":"notion"},{"slug":"transfert-partage","title":"Transfert / partage","definition":"Mécanisme qui fait supporter à un tiers une partie des conséquences, notamment financières ; il ne supprime pas nécessairement le risque.","kind":"notion"},{"slug":"tracabilite","title":"Traçabilité","definition":"Capacité à retrouver ce qui a été demandé, à qui, quand, avec quelles pièces et quelle réponse.","kind":"notion"},{"slug":"tracabilite-du-contact","title":"Traçabilité du contact","definition":"Enregistrement de la date, du canal, de l’interlocuteur, du résultat et de la prochaine action.","kind":"notion"},{"slug":"tresorerie","title":"Trésorerie","definition":"Disponibilités monétaires permettant à la PME de faire face à ses paiements à une date donnée.","kind":"notion"},{"slug":"tresorerie-nette","title":"Trésorerie nette","definition":"Équilibre résultant de la relation entre ressources stables et besoin en fonds de roulement dans l’analyse fonctionnelle.","kind":"indicateur"},{"slug":"tva","title":"TVA","definition":"Taxe sur la valeur ajoutée collectée ou déductible selon les opérations et règles applicables.","kind":"regle"},{"slug":"tva-collectee","title":"TVA collectée","definition":"TVA facturée aux clients par l’entreprise sur les opérations qui y sont soumises.","kind":"regle"},{"slug":"tva-deductible","title":"TVA déductible","definition":"TVA supportée sur certains achats et que l’entreprise peut déduire lorsque les conditions sont remplies.","kind":"regle"},{"slug":"tva-a-payer-credit-de-tva","title":"TVA à payer / crédit de TVA","definition":"Solde obtenu après comparaison de la TVA due et de la TVA déductible pour la période concernée.","kind":"regle"},{"slug":"type-d-absence","title":"Type d’absence","definition":"Motif et régime de l’absence : congé, maladie, autorisation, accident, absence non justifiée, etc. ; le traitement dépend du cas.","kind":"regle"},{"slug":"tache","title":"Tâche","definition":"Travail élémentaire à réaliser, confié à un responsable et associé à une durée ou une échéance.","kind":"notion"},{"slug":"unite-de-travail","title":"Unité de travail","definition":"Regroupement cohérent de situations de travail permettant d’évaluer les risques dans des conditions comparables.","kind":"notion"},{"slug":"valeur-de-reference","title":"Valeur de référence","definition":"Point de départ ou période de comparaison servant à mesurer une évolution.","kind":"indicateur"},{"slug":"validation-des-donnees","title":"Validation des données","definition":"Fonction qui limite ou contrôle les valeurs autorisées lors de la saisie dans une cellule ou un champ.","kind":"outil"},{"slug":"variable-de-paie","title":"Variable de paie","definition":"Information qui change d’une période à l’autre et influence la paie : heures, absence, prime, avantage, remboursement, etc.","kind":"notion"},{"slug":"veille","title":"Veille","definition":"Démarche organisée pour surveiller des informations utiles et repérer des évolutions importantes.","kind":"methode"},{"slug":"version-de-procedure","title":"Version de procédure","definition":"État daté et identifié d’une procédure afin de savoir quelle règle interne est applicable.","kind":"notion"},{"slug":"version-de-reference","title":"Version de référence","definition":"Version considérée comme valide et à utiliser ; elle doit être identifiable sans ambiguïté.","kind":"notion"},{"slug":"violation-de-donnees","title":"Violation de données","definition":"Incident de sécurité entraînant destruction, perte, altération, divulgation non autorisée ou accès non autorisé à des données personnelles.","kind":"notion"}];